"""Image gallery for profile banners (files generated by scripts/make_profile_gallery.py).

Members can only pick from these keys: no upload, so nothing to moderate or store.
"""

from flask import url_for

# key: (label fr, label en)
BANNERS = {
    "aurora": ("Aurore boréale", "Northern lights"),
    "nebula": ("Nébuleuse", "Nebula"),
    "synthwave": ("Synthwave", "Synthwave"),
    "mountains": ("Crépuscule", "Dusk mountains"),
    "ocean": ("Océan de nuit", "Night ocean"),
    "lowpoly": ("Low poly", "Low poly"),
    "topo": ("Topographie", "Topography"),
    "pixel": ("Ville pixel", "Pixel city"),
    "sakura": ("Sakura", "Sakura"),
    "ember": ("Braises", "Embers"),
    "circuit": ("Circuit", "Circuit"),
    "dunes": ("Dunes", "Dunes"),
    # pop culture moods (original art inspired by anime and video game aesthetics)
    "neon_city": ("Ville néon", "Neon city"),
    "pixel_dungeon": ("Donjon pixel", "Pixel dungeon"),
    "arcade": ("Arcade 8-bit", "8-bit arcade"),
    "great_wave": ("Grande vague", "Great wave"),
    "anime_sky": ("Ciel d’animé", "Anime sky"),
    "torii": ("Sanctuaire", "Shrine"),
    "manga": ("Manga", "Manga"),
    "mecha_hud": ("HUD mecha", "Mecha HUD"),
    "enchanted_forest": ("Forêt enchantée", "Enchanted forest"),
    "platformer": ("Plateformes rétro", "Retro platformer"),
    "vaporwave": ("Vaporwave", "Vaporwave"),
    "planet": ("Planète", "Planet"),
    "hyperspace": ("Hyperespace", "Hyperspace"),
    "code_rain": ("Pluie de code", "Code rain"),
    "crystal_cave": ("Grotte de cristal", "Crystal cave"),
    "lava_world": ("Monde de lave", "Lava world"),
    "snow_night": ("Nuit enneigée", "Snowy night"),
    "deep_sea": ("Abysses", "Deep sea"),
    "blood_moon": ("Lune de sang", "Blood moon"),
    "block_world": ("Monde de blocs", "Block world"),
    "desert_ruins": ("Ruines du désert", "Desert ruins"),
    "lofi_rain": ("Lo-fi pluie", "Lo-fi rain"),
    "galaxy": ("Galaxie", "Galaxy"),
    "storm": ("Orage", "Storm"),
}



def banner_url(key: str | None, thumb: bool = False) -> str | None:
    if key not in BANNERS:
        return None
    return url_for("static", filename=f"images/profile/banners/{key}{'_thumb' if thumb else ''}.webp")


def gallery(items: dict, url_fn, lang: str) -> list[dict]:
    """Picker entries: key, label, thumbnail and full image URL."""
    return [
        {"key": key, "label": fr if lang == "fr" else en, "thumb": url_fn(key, thumb=True), "url": url_fn(key)}
        for key, (fr, en) in items.items()
    ]
